   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 9 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_FOLLOW_UP_CHASE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 0 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     FOLLOW_UP_INTIMATION_DATE              opus_health_v2         2 writer(s), of which 1 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , FOLLOWUP_ID as FOLLOW_UP_REFERENCE
        , ORPHAN_ID as ORPHAN_RECORD_REFERENCE
        , DOCUMENT_FROM as DOCUMENT_SOURCE_STAGE
        , FOLLOWUP_REASON as FOLLOW_UP_REASON
        , UPDATED_ON as FOLLOW_UP_INTIMATION_DATE
        , FIR_REM_DATE as FIRST_REMINDER_DATE
        , SEC_REM_DATE as SECOND_REMINDER_DATE
        , REPLY_DATE as REPLY_RECEIVED_DATE
        , UPDATED_BY as FOLLOW_UP_UPDATED_BY_USER_REFERENCE
        , 'BJAZ_HM_ORPHAN_FOLLOW_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_orphan_follow_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then FOLLOW_UP_REFERENCE end) as FOLLOW_UP_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ORPHAN_RECORD_REFERENCE end) as ORPHAN_RECORD_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then DOCUMENT_SOURCE_STAGE end) as DOCUMENT_SOURCE_STAGE,
        max(case when SOURCE_RUN = 'opus_health_v2' then FOLLOW_UP_REASON end) as FOLLOW_UP_REASON,
        max(case when SOURCE_RUN = 'opus_health_v2' then FOLLOW_UP_INTIMATION_DATE end) as FOLLOW_UP_INTIMATION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then FIRST_REMINDER_DATE end) as FIRST_REMINDER_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then SECOND_REMINDER_DATE end) as SECOND_REMINDER_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then REPLY_RECEIVED_DATE end) as REPLY_RECEIVED_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then FOLLOW_UP_UPDATED_BY_USER_REFERENCE end) as FOLLOW_UP_UPDATED_BY_USER_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when FOLLOW_UP_REFERENCE is not null or ORPHAN_RECORD_REFERENCE is not null or DOCUMENT_SOURCE_STAGE is not null or FOLLOW_UP_REASON is not null or FOLLOW_UP_INTIMATION_DATE is not null or FIRST_REMINDER_DATE is not null or SECOND_REMINDER_DATE is not null or REPLY_RECEIVED_DATE is not null or FOLLOW_UP_UPDATED_BY_USER_REFERENCE is not null
                     then md5(upper(coalesce(cast(FOLLOW_UP_REFERENCE as varchar), '') || '|' || coalesce(cast(ORPHAN_RECORD_REFERENCE as varchar), '') || '|' || coalesce(cast(DOCUMENT_SOURCE_STAGE as varchar), '') || '|' || coalesce(cast(FOLLOW_UP_REASON as varchar), '') || '|' || coalesce(cast(FOLLOW_UP_INTIMATION_DATE as varchar), '') || '|' || coalesce(cast(FIRST_REMINDER_DATE as varchar), '') || '|' || coalesce(cast(SECOND_REMINDER_DATE as varchar), '') || '|' || coalesce(cast(REPLY_RECEIVED_DATE as varchar), '') || '|' || coalesce(cast(FOLLOW_UP_UPDATED_BY_USER_REFERENCE as varchar), '')))
                end as SAT_CLAIM_FOLLOW_UP_CHASE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_FOLLOW_UP_CHASE_HASHDIFF is not null
